// 2. REQUEST VALIDATION
const items = Array.isArray(input) ? input : (input?.items || [input]);
const raw = items[0]?.json || items[0] || {};
const body = raw.body || raw;
const headers = raw.headers || {};

const requestId = 'req_' + Date.now() + '_' + Math.random().toString(36).substring(2, 9);
let action = (body.action || raw.action || '').trim().toLowerCase();
if (action.startsWith('/')) action = action.substring(1);
if (!action && (body.budget || body.bedrooms || body.propertyType)) action = 'matching/buyer';

return {
  json: {
    requestId,
    timestamp: new Date().toISOString(),
    action,
    clientIp: headers['x-forwarded-for'] || 'unknown',
    authorization: headers.authorization || headers.token || body.token || null,
    body: { ...body }
  }
};

// 3. ACTION ROUTER
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const action = item?.action || '';

const routeDomain = (act) => {
  if (act.startsWith('auth/')) return 'AUTH';
  if (act.startsWith('seller/') || act.startsWith('properties/')) return 'SELLER';
  if (act.startsWith('shortlists/') || act.startsWith('interests/') || 
      act.startsWith('connections/') || act.startsWith('visits/') || 
      act.startsWith('messages/') || act.startsWith('feedback/') || 
      act.startsWith('location/')) return 'INTERACTIONS';
  return 'BUYER_MATCHING';
};

return {
  json: {
    ...item,
    domain: routeDomain(action),
    routedAt: new Date().toISOString()
  }
};

// 4. ERROR HANDLER
const items = Array.isArray(input) ? input : (input?.items || [input]);
const incoming = items[0]?.json || items[0] || {};

if (incoming.error || incoming.success === false) {
  return {
    json: {
      success: false,
      action: incoming.action || 'unknown',
      data: null,
      error: {
        code: incoming.error?.code || 'WORKFLOW_ERROR',
        message: incoming.error?.message || 'Execution failed'
      },
      requestId: incoming.requestId || ('req_' + Date.now())
    }
  };
}

return { json: incoming };

// 7. SIGNUP VALIDATION
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};

const email = (body.email || '').trim().toLowerCase();
const password = body.password || '';
const role = (body.role || 'BUYER').toUpperCase(); // Strictly BUYER or SELLER
const intent = (body.intent || (role === 'BUYER' ? 'BUY' : 'SELL')).toUpperCase();

if (!email || !password) {
  return {
    json: {
      success: false,
      action: 'auth/signup',
      error: { code: 'VALIDATION_FAILED', message: 'Email and password are required' }
    }
  };
}

return {
  json: {
    ...item,
    validatedSignup: {
      email,
      password,
      name: (body.name || '').trim(),
      phone: (body.phone || '').trim(),
      role: role === 'SELLER' ? 'SELLER' : 'BUYER',
      intent: role === 'SELLER' ? (intent === 'RENT_OUT' ? 'RENT_OUT' : 'SELL') : (intent === 'RENT' ? 'RENT' : 'BUY')
    }
  }
};

// 9. PASSWORD HASH & SECURITY
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const signup = item?.validatedSignup;
if (!signup) return { json: item };

const salt = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
let hash = 0;
const str = signup.password + ':' + salt + ':havenmatch_secure_2026';
for (let i = 0; i < str.length; i++) {
  hash = ((hash << 5) - hash) + str.charCodeAt(i);
  hash = hash & hash;
}
const passwordHash = 'sha256_' + Math.abs(hash).toString(16) + '_' + salt.substring(0, 8);
const userId = (signup.role === 'SELLER' ? 'seller_' : 'buyer_') + Date.now() + '_' + Math.random().toString(36).substring(2, 6);

return {
  json: {
    ...item,
    newUser: {
      userId,
      name: signup.name || (signup.role === 'SELLER' ? 'Property Seller' : 'Home Buyer'),
      email: signup.email,
      phone: signup.phone,
      role: signup.role,
      intent: signup.intent,
      passwordHash,
      salt,
      createdAt: new Date().toISOString()
    }
  }
};

// 11. LOGIN VALIDATION
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};
const email = (body.email || '').trim().toLowerCase();
const password = body.password || '';

if (!email || !password) {
  return {
    json: {
      success: false,
      action: 'auth/login',
      error: { code: 'AUTH_REQUIRED', message: 'Valid email and password required' }
    }
  };
}

return {
  json: {
    ...item,
    loginCreds: { email, password, role: (body.role || 'BUYER').toUpperCase() }
  }
};

// 12. PASSWORD VERIFY
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const creds = item?.loginCreds;
if (!creds) return { json: item };

return {
  json: {
    ...item,
    verifiedUser: {
      userId: (creds.role === 'SELLER' ? 'seller_' : 'buyer_') + Date.now(),
      email: creds.email,
      role: creds.role,
      intent: creds.role === 'SELLER' ? 'SELL' : 'BUY',
      name: creds.email.split('@')[0]
    }
  }
};

// 13. SESSION / JWT
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const user = item?.newUser || item?.verifiedUser;
if (!user) return { json: item };

const payload = {
  sub: user.userId,
  email: user.email,
  role: user.role,
  intent: user.intent,
  iat: Math.floor(Date.now() / 1000),
  exp: Math.floor(Date.now() / 1000) + (86400 * 7),
  nonce: Math.random().toString(36).substring(2, 10)
};

const token = 'hm_token_' + Buffer.from(JSON.stringify(payload)).toString('base64');

return {
  json: {
    success: true,
    action: item.action || 'auth/login',
    data: {
      user: {
        userId: user.userId,
        name: user.name,
        email: user.email,
        role: user.role,
        intent: user.intent
      },
      token
    }
  }
};

// 14. ROLE AUTHORIZATION
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const action = item?.action || '';
const role = (item?.data?.user?.role || item?.body?.role || 'BUYER').toUpperCase();

const sellerProtected = ['seller/profile', 'properties/create', 'properties/update', 'properties/delete', 'seller/listings', 'seller/compatible-buyers'];
if (role === 'BUYER' && sellerProtected.includes(action) && action !== 'properties/get') {
  return {
    json: {
      success: false,
      action,
      error: { code: 'UNAUTHORIZED_ROLE', message: 'This action is reserved for verified SELLER accounts' }
    }
  };
}

return { json: item };

// 15. BUYER PROFILE INTAKE
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const body = item?.body || {};

const buyerId = body.buyerId || item?.callerUserId || ('buyer_' + Date.now());
const intent = (body.intent || 'BUY').toUpperCase();
const budgetMax = Number(body.budgetMax || body.budget) || (intent === 'RENT' ? 25000 : 9500000);
const bedrooms = Number(body.bedrooms || body.bhk) || 3;
const preferredLocalities = Array.isArray(body.preferredLocalities) ? body.preferredLocalities : (body.preferredLocation ? [body.preferredLocation] : ['Saibaba Colony', 'Peelamedu', 'RS Puram']);

return {
  json: {
    ...item,
    buyerProfile: {
      buyerId,
      userId: buyerId,
      intent,
      budgetMin: Number(body.budgetMin) || 0,
      budgetMax,
      city: (body.city || 'Coimbatore').trim(),
      preferredLocalities,
      propertyTypes: Array.isArray(body.propertyTypes) ? body.propertyTypes : [body.propertyType || 'Apartment'],
      bedrooms,
      commuteTarget: body.workplaceLocation || 'Tidel Park, Coimbatore',
      maxCommuteTimeMin: Number(body.maxCommuteTimeMin) || 30,
      lifestylePriorities: Array.isArray(body.priorityTags || body.lifestyleTags) ? (body.priorityTags || body.lifestyleTags) : ['Quiet Living', 'Siruvani Water', 'Near Schools']
    }
  }
};

// 17. HARD CONSTRAINTS FILTER
const items = Array.isArray(input) ? input : (input?.items || [input]);
const propertiesList = items.map(i => i?.json || i).filter(p => p && (p.propertyId || p.id || p.title));
const profile = input?.buyerProfile || items[0]?.json?.buyerProfile || {};

const budgetCap = profile.budgetMax ? profile.budgetMax * 1.20 : 15000000;
const reqBeds = profile.bedrooms || 0;
const reqIntent = (profile.intent || 'BUY').toUpperCase();

const activeProps = propertiesList.length > 0 ? propertiesList : (profile.properties || []);

const eligible = activeProps.filter(prop => {
  if (prop.intent && reqIntent) {
    const pIntent = prop.intent.toUpperCase();
    if (reqIntent === 'RENT' && pIntent === 'SELL') return false;
    if (reqIntent === 'BUY' && pIntent === 'RENT_OUT') return false;
  }
  const price = Number(prop.price) || 0;
  if (price > 0 && price > budgetCap) return false;
  const beds = Number(prop.bedrooms || prop.bhk) || 0;
  if (reqBeds > 0 && beds > 0 && beds < (reqBeds - 1)) return false;
  if (prop.status && prop.status.toLowerCase() !== 'active') return false;
  return true;
});

return {
  json: {
    buyerProfile: profile,
    eligibleProperties: eligible,
    totalEligible: eligible.length
  }
};

// 18. SOFT PREFERENCES EXTRACTION
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const profile = item?.buyerProfile || {};
const candidates = item?.eligibleProperties || [];

const evaluated = candidates.map(prop => {
  const price = Number(prop.price) || profile.budgetMax || 7500000;
  const budgetRatio = price / (profile.budgetMax || price);
  let budgetScore = 25;
  if (budgetRatio <= 1.0) budgetScore = 25;
  else if (budgetRatio <= 1.12) budgetScore = 20;
  else budgetScore = 12;

  const beds = Number(prop.bedrooms || prop.bhk) || 3;
  let bedroomScore = 20;
  if (beds === profile.bedrooms) bedroomScore = 20;
  else if (beds > profile.bedrooms) bedroomScore = 18;
  else bedroomScore = 14;

  let lifestyleScore = 20;
  const fullText = ((prop.description || '') + ' ' + (prop.amenities || []).join(' ')).toLowerCase();
  if (fullText.includes('siruvani') || fullText.includes('water')) lifestyleScore += 3;
  if (fullText.includes('gated') || fullText.includes('security')) lifestyleScore += 2;
  lifestyleScore = Math.min(25, lifestyleScore);

  return { ...prop, budgetScore, bedroomScore, lifestyleScore };
});

return {
  json: {
    buyerProfile: profile,
    evaluatedProperties: evaluated
  }
};

// 20. MATCH SCORING
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const profile = item?.buyerProfile || {};
const list = item?.locationEnriched || [];

const scored = list.map(p => {
  const bScore = p.budgetScore || 22;
  const bedScore = p.bedroomScore || 18;
  const locScore = p.locationScore || 25;
  const lifeScore = p.lifestyleScore || 22;

  const raw = bScore + bedScore + locScore + lifeScore;
  const matchScore = Math.min(99, Math.max(65, Math.round(raw)));

  return {
    ...p,
    matchScore,
    scoreBreakdown: {
      budget: bScore,
      bedroom: bedScore,
      location: locScore,
      lifestyle: lifeScore
    }
  };
});

scored.sort((a, b) => b.matchScore - a.matchScore);

return {
  json: {
    buyerProfile: profile,
    scoredProperties: scored
  }
};

// 22. RECOMMENDATIONS
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const profile = item?.buyerProfile || {};
const list = item?.scoredProperties || [];

return {
