// 23. WHY THIS PROPERTY?
const item = Array.isArray(input) ? input[0]?.json || input[0] : input?.json || input;
const profile = item?.buyerProfile || {};
const recs = item?.recommendations || [];

const explained = recs.map((prop, idx) => {
  const reasons = [
    `Priced within target budget parameters`,
    `${prop.bedrooms || prop.bhk || 3} BHK configuration matching space requirements`,
    `${prop.commuteTimeMin || 18} min commute buffer to target workplace corridor`
  ];
  if ((prop.amenities || []).some(a => /water|siruvani/i.test(a))) {
    reasons.push('Verified Siruvani drinking water infrastructure');
  }

  const tradeOffs = [];
  if (prop.price > (profile.budgetMax || 7000000) * 0.92) {
    tradeOffs.push('Near upper limit of budget ceiling');
  }
  if ((prop.commuteTimeMin || 0) > 22) {
    tradeOffs.push('Slight commute buffer during peak rush hours');
  }

  return {
    ...prop,
    propertyId: prop.propertyId || prop.id,
    rank: idx + 1,
    whyThisProperty: reasons,
    tradeOffs: tradeOffs.length > 0 ? tradeOffs : ['High demand residential enclave with strong appreciation'],
    locationFit: `${prop.locality || prop.city || 'Coimbatore'} (${prop.distanceKm || 4.2} km to IT Corridor)`
  };
});

const matchId = 'match_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6);

return {
  json: {
    success: true,
    action: 'matching/buyer',
    data: {
      matchId,
      buyerId: profile.buyerId,
      matchCount: explained.length,
      recommendations: explained,
